package pe.edu.upeu.casaonada.orden.service;
import pe.edu.upeu.casaonada.orden.domain.*; import pe.edu.upeu.casaonada.orden.dto.*; import pe.edu.upeu.casaonada.orden.exception.*; import pe.edu.upeu.casaonada.orden.repository.OrdenRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@Service public class OrdenService { private final OrdenRepository repo; public OrdenService(OrdenRepository r){repo=r;}
 @Transactional public OrdenResponse crear(OrdenRequest r){ Orden o=new Orden(); o.setClienteId(r.clienteId());o.setReservaId(r.reservaId());o.setTipoOperacion(r.tipoOperacion());o.setMoneda(r.moneda().toUpperCase());o.setMontoAdelanto(r.montoAdelanto());o.setEstado(EstadoOrden.CREADA); BigDecimal subtotal=BigDecimal.ZERO; for(var d:r.detalles()){DetalleOrden x=new DetalleOrden();x.setPropiedadId(d.propiedadId());x.setConcepto(d.concepto());x.setPrecioAcordado(d.precioAcordado());o.agregarDetalle(x);subtotal=subtotal.add(d.precioAcordado());} o.setSubtotal(subtotal);o.setTotal(subtotal); return map(repo.save(o)); }
 @Transactional(readOnly=true) public List<OrdenResponse> listar(){return repo.findAll().stream().map(this::map).toList();} @Transactional(readOnly=true) public OrdenResponse buscar(Long id){return map(entity(id));}
 @Transactional public OrdenResponse cambiarEstado(Long id,EstadoOrden nuevo){Orden o=entity(id); if(nuevo==EstadoOrden.CONFIRMADA && o.getEstado()!=EstadoOrden.PAGO_APROBADO) throw new BusinessRuleException("La orden solo puede confirmarse después de un pago aprobado"); o.setEstado(nuevo); return map(repo.save(o));}
 private Orden entity(Long id){return repo.findOneById(id).orElseThrow(()->new ResourceNotFoundException("Orden no encontrada: "+id));} private OrdenResponse map(Orden o){return new OrdenResponse(o.getId(),o.getClienteId(),o.getReservaId(),o.getTipoOperacion(),o.getMoneda(),o.getSubtotal(),o.getTotal(),o.getMontoAdelanto(),o.getEstado(),o.getDetalles().stream().map(d->new DetalleOrdenResponse(d.getId(),d.getPropiedadId(),d.getConcepto(),d.getPrecioAcordado())).toList(),o.getCreatedAt(),o.getUpdatedAt());} }
